import ipaddress  # type: ignore
import six

from taf.config.testline import CloudBts, ClassicalBts, NetworkAddress


class GnbAttrs(object):

    def __init__(self, gnb_list):
        self.gnbs = gnb_list

    def get_vnf_prefix(self):
        for gnb in self.gnbs:
            if isinstance(gnb, CloudBts):
                return gnb.cloud_deployment.flavors[0].default_vnf_prefix
        msg = 'In testline.gnbs there is no gnb.cloud_deployment.flavors[0].default_vnf_prefix'
        raise AttributeError(msg)

    def has_cloudBts(self):
        return any(isinstance(gnb, CloudBts) for gnb in self.gnbs)

    def get_du_list(self):
        gnb = self.gnbs[0]
        return gnb.dus if gnb.dus is not None else []

    def get_number_of_du(self):
        for gnb in self.gnbs:
            if gnb.dus is not None:
                return len(gnb.dus)
        return 0

    def is_backhaul_ipv6(self):
        backhaul_oam_ip = self.gnbs[0].cu.backhaul_site_oam_ip
        if isinstance(backhaul_oam_ip, NetworkAddress):
            return backhaul_oam_ip.v6 is not None
        else:
            oam_ip_address = backhaul_oam_ip
            if six.PY2:
                oam_ip_address = oam_ip_address.decode('utf-8')
            return isinstance(ipaddress.ip_address(oam_ip_address),
                              ipaddress.IPv6Address)

    def get_cloudbts_gnbs(self):
        if self.gnbs is None:
            raise AttributeError('No gnb in testline object.')
        return [gnb for gnb in self.gnbs if isinstance(gnb, CloudBts)]

    def get_classicalbts_gnbs(self):
        if self.gnbs is None:
            raise AttributeError('No gnb in testline object.')
        return [gnb for gnb in self.gnbs if isinstance(gnb, ClassicalBts)]
